options.customCss:
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap');

:root {
	--font-family: 'Cairo', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 700;
	--font-size-body: 14px;
	--font-size-label: 16px;
	--font-size-test-notice: 12px;
	--font-size-input: 15px;
	--font-size-header: 26px;
	--font-size-paragraph: 15px;
	--font-size-link: 13px;
	--font-size-error: 13px;
	--font-size-html-h1: 28px;
	--font-size-html-h2: 22px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 16px;
	--font-size-html-h5: 14px;
	--font-size-html-h6: 12px;
	--font-size-subheader: 15px;

	/* Colors */
	--color-background: #fbf3e8;
	--color-test-notice-text: #b9772a;
	--color-test-notice-bg: #fff6e8;
	--color-test-notice-border: #f0d4a8;
	--color-card-bg: #fffdf9;
	--color-card-border: #ecdcc8;
	--color-card-shadow: rgba(120, 72, 30, 0.10);
	--color-link: #9a7b62;
	--color-header: #4a3426;
	--color-label: #6b4f3a;
	--color-input-border: #e6d3bb;
	--color-input-text: #4a3426;
	--color-focus-border: #d9822b;
	--color-submit-btn-bg: #d9822b;
	--color-submit-btn-text: #ffffff;
	--color-error: #c0392b;
	--color-required: #d9822b;
	--color-clear-button-bg: #9a7b62;
	--color-html-text: #6b4f3a;
	--color-html-link: #d9822b;
	--color-header-subtext: #9a7b62;

	/* Border Radii */
	--border-radius-card: 16px;
	--border-radius-input: 12px;
	--border-radius-clear-btn: 50%;
	--card-border-radius: 16px;

	/* Spacing */
	--padding-container-top: 32px;
	--padding-card: 32px;
	--padding-test-notice-vertical: 12px;
	--padding-test-notice-horizontal: 24px;
	--margin-bottom-card: 20px;
	--padding-form-input: 14px;
	--card-padding: 32px;
	--card-margin-bottom: 20px;

	/* Dimensions */
	--container-width: 480px;
	--submit-btn-height: 52px;
	--checkbox-size: 20px;

	/* Others */
	--box-shadow-card: 0px 8px 24px 0px var(--color-card-shadow);
	--opacity-placeholder: 0.45;
}

/* ===== اتجاه الفورم عربي ===== */
html, body, form, .card, .form-group, .form-input, .form-header {
	direction: rtl;
	text-align: right;
}

label,
.form-label,
.form-group label {
	display: block;
	width: 100%;
	text-align: right;
	direction: rtl;
}

input,
textarea,
select {
	direction: rtl;
	text-align: right;
}

/* العناوين والوصف في النص */
h1, h2, .form-header, .form-header * {
	text-align: center;
}

/* ===== Responsive ===== */

/* أساسيات تمنع الخروج عن الشاشة */
*, *::before, *::after {
	box-sizing: border-box;
}

html, body {
	max-width: 100%;
	overflow-x: hidden;
}

input, textarea, select, button {
	max-width: 100%;
	font-family: inherit;
}

textarea {
	min-height: 120px;
	resize: vertical;
}

/* تابلت */
@media (max-width: 768px) {
	:root {
		--container-width: 100%;
		--padding-container-top: 24px;
		--padding-card: 24px;
		--card-padding: 24px;
		--font-size-header: 24px;
	}
}

/* ===== موبايل ===== */
@media (max-width: 480px) {

	/* مسافة حوالين الكارت من حافة الشاشة */
	body {
		padding: 16px 14px !important;
	}

	/* الكارت الأبيض: حواف دايرية + padding مريح */
	form,
	.card,
	.form-card,
	.container > div {
		width: 100% !important;
		max-width: 100% !important;
		margin: 0 auto !important;
		border-radius: 20px !important;
		padding: 28px 22px !important;
		box-shadow: 0px 8px 24px 0px rgba(120, 72, 30, 0.10) !important;
		border: 1px solid #ecdcc8 !important;
		overflow: hidden;
	}

	/* العنوان والوصف */
	.form-header, h1, h2 {
		font-size: 22px !important;
		margin: 0 0 10px 0 !important;
		line-height: 1.5;
	}

	/* مسافة معتدلة بين الحقول */
	.form-group, .form-input {
		margin-bottom: 18px !important;
		padding: 0 !important;
	}

	label {
		font-size: 14px !important;
		margin-bottom: 6px !important;
	}

	/* الحقول أصغر وأنعم */
	input, textarea, select {
		font-size: 16px !important; /* مهم عشان iPhone ما يعملش zoom */
		padding: 10px 14px !important;
		min-height: 44px !important;
		height: auto !important;
		border-radius: 12px !important;
		width: 100% !important;
	}

	textarea {
		min-height: 100px !important;
	}

	/* الزرار */
	button, [type="submit"] {
		width: 100% !important;
		height: 48px !important;
		min-height: 48px !important;
		border-radius: 12px !important;
		font-size: 16px !important;
		margin-top: 8px !important;
	}
}

